// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address owner = 0x9797055B68C5DadDE6b3c7d5D80C9CFE2eecE6c9;

    function setUp() public { c = new C(); }

    // fuzzed param: a non-empty array length and a single recipient address and value
    function testFuzz_property(address to, uint256 v) public {
        // keep to wide but non-zero address to avoid accidentally being zero address
        vm.assume(to != address(0));
        // construct arrays inline
        address[] memory tos = new address[](1);
        tos[0] = to;
        uint[] memory vals = new uint[](1);
        vals[0] = v;

        // ensure owner has enough ETH not required here but keep environment predictable
        vm.deal(owner, 1 ether);

        // call transfer as the hardcoded owner: reference C should allow this and return true (not revert)
        bool ok;
        vm.prank(owner);
        try c.transfer(tos, vals) {
            ok = true;
        } catch {
            ok = false;
        }

        // The universal property: the reference accepts calls from the hardcoded owner for any admissible inputs.
        // For the mutant (which flips the require), calling from the hardcoded owner will revert for some inputs,
        // so this assertion will fail on that mutant for those inputs.
        assertTrue(ok);
    }
}
